using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDay.Api.Data;using RaceDay.Api.DTOs;using RaceDay.Api.Models;using System.Security.Claims;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api/enrolments")]
public class EnrolmentsController(RaceDayContext db):ControllerBase{
 [HttpGet("mine"),Authorize(Roles="Participant"),ProducesResponseType(typeof(IEnumerable<EnrolmentResponse>),200)] public async Task<IActionResult> Mine(){var id=User.CurrentUserId();return Ok(await Query().Where(x=>x.ParticipantID==id).Select(ToDto()).ToListAsync());}
 [HttpGet,Authorize(Roles="Organiser"),ProducesResponseType(typeof(IEnumerable<EnrolmentResponse>),200)] public async Task<IActionResult> All([FromQuery]int? eventId){var q=Query();if(eventId.HasValue)q=q.Where(x=>x.EventID==eventId.Value);return Ok(await q.Select(ToDto()).ToListAsync());}
 [HttpPost,Authorize(Roles="Participant"),ProducesResponseType(typeof(EnrolmentResponse),201),ProducesResponseType(400)] public async Task<IActionResult> Enrol(EnrolmentRequest r){var id=User.CurrentUserId();var ec=await db.EventCategories.Include(x=>x.Event).Include(x=>x.Enrolments).SingleOrDefaultAsync(x=>x.EventID==r.EventID&&x.CategoryID==r.CategoryID);if(ec is null)return NotFound(new{message="Event/category offering not found."});if(ec.Event!.Status!="Open")return BadRequest(new{message="This event is not open for enrolment."});var existing=await db.Enrolments.SingleOrDefaultAsync(x=>x.ParticipantID==id&&x.EventID==r.EventID&&x.CategoryID==r.CategoryID);if(existing is not null&&existing.Status!="Cancelled")return Conflict(new{message="You are already enrolled in this category."});if(ec.Enrolments.Count(x=>x.Status=="Confirmed")>=ec.Capacity)return Conflict(new{message="This category is full."});if(existing is not null){existing.Status="Confirmed";existing.EnrolmentDate=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(await Query().Where(x=>x.EnrolmentID==existing.EnrolmentID).Select(ToDto()).SingleAsync());}var e=new Enrolment{EventID=r.EventID,CategoryID=r.CategoryID,ParticipantID=id,Status="Confirmed",EnrolmentDate=DateTime.UtcNow};db.Enrolments.Add(e);await db.SaveChangesAsync();return CreatedAtAction(nameof(Mine),new{ id=e.EnrolmentID },await Query().Where(x=>x.EnrolmentID==e.EnrolmentID).Select(ToDto()).SingleAsync());}
 [HttpDelete("{id:int}"),Authorize(Roles="Participant"),ProducesResponseType(204),ProducesResponseType(404)] public async Task<IActionResult> Cancel(int id){var e=await db.Enrolments.SingleOrDefaultAsync(x=>x.EnrolmentID==id&&x.ParticipantID==User.CurrentUserId());if(e is null)return NotFound();if(await db.Results.AnyAsync(x=>x.EnrolmentID==id))return Conflict(new{message="An enrolment with a result cannot be cancelled."});e.Status="Cancelled";await db.SaveChangesAsync();return NoContent();}
 private IQueryable<Enrolment> Query()=>db.Enrolments.AsNoTracking().Include(x=>x.Participant).Include(x=>x.EventCategory).ThenInclude(x=>x!.Event).Include(x=>x.EventCategory).ThenInclude(x=>x!.Category);
 private static System.Linq.Expressions.Expression<Func<Enrolment,EnrolmentResponse>> ToDto()=>x=>new EnrolmentResponse(x.EnrolmentID,x.EventID,x.EventCategory!.Event!.EventName,x.CategoryID,x.EventCategory.Category!.CategoryName,x.ParticipantID,x.Participant!.FirstName+" "+x.Participant.LastName,x.EnrolmentDate,x.Status);
}
